import{_ as o,C as n,c as r,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Payments","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/orders-payments/payments.md","filePath":"master/sales/point-of-sale/orders-payments/payments.md","lastUpdated":1792041590000}'),l={name:"master/sales/point-of-sale/orders-payments/payments.md"};function h(m,e,d,p,g,u){const s=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="payments" tabindex="-1">Payments <a class="header-anchor" href="#payments" aria-label="Permalink to &quot;Payments&quot;">​</a></h1><p>A payment is one amount a customer handed over for an order, with the method used. An order can have several payments, for example part cash and part card. The Payments page lists them all, so you can check what each method took in.</p><blockquote><p><strong>In simple words:</strong> Payments is the money list. Each row is one amount paid on one order.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Go to <code>Point of Sale → Orders → Payments</code>.</p>',5)),a(s,{src:"/images1/pos/payments_list.png",alt:"Point of Sale → Orders → Payments list with Cash payments for TNE/00001 and TNE/00002"}),e[1]||(e[1]=t('<p>The page has these tabs:</p><ul><li><strong>All:</strong> Every payment.</li><li><strong>Today:</strong> Payments made today.</li></ul><p>The saved views menu also holds <strong>Change</strong>, which lists only the change lines.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Order:</em></strong> The order the payment belongs to, such as <strong>TNE/00001</strong>.</li><li><strong><em>Session:</em></strong> The session, such as <strong>TNE/SESSION/00002</strong>.</li><li><strong><em>Method:</em></strong> The payment method, such as <strong>Cash</strong>.</li><li><strong><em>Amount:</em></strong> The amount. Refunds and change are negative.</li><li><strong><em>Change:</em></strong> A tick when the line is the change given back to the customer.</li><li><strong><em>Paid At:</em></strong> The date and time of the payment.</li></ul><p>Hidden columns: <strong>Customer</strong> and <strong>Terminal Status</strong>.</p><h3 id="group-and-filter" tabindex="-1">Group and filter <a class="header-anchor" href="#group-and-filter" aria-label="Permalink to &quot;Group and filter&quot;">​</a></h3><ul><li>Click <strong>Group by</strong> to group by <strong>Method</strong> or <strong>Session</strong>.</li><li>Use the filters for <strong>Payment Method</strong> and <strong>Session</strong>.</li></ul><h2 id="read-the-rows" tabindex="-1">Read the rows <a class="header-anchor" href="#read-the-rows" aria-label="Permalink to &quot;Read the rows&quot;">​</a></h2><p>Look at order <strong>TNE/00001</strong>. It shows two rows:</p><ul><li><strong>Cash</strong> 7,000. This is what Sofia Rossi handed over.</li><li><strong>Cash</strong> -403 with <strong>Change</strong> ticked. This is the change you gave back.</li></ul><p>The net cash taken is 6,597, the order total.</p><p>A refund shows a negative payment. The refund order <strong>TNE/00002 REFUND</strong> has a <strong>Cash</strong> line of -24,999.</p>',13)),a(s,{src:"/images1/pos/payments_group_by_method.png",alt:"Payments list grouped by Method showing Cash rows with amounts and change lines"}),e[2]||(e[2]=t('<h2 id="where-payments-come-from" tabindex="-1">Where payments come from <a class="header-anchor" href="#where-payments-come-from" aria-label="Permalink to &quot;Where payments come from&quot;">​</a></h2><p>You do not create payments here. The cashier takes them on the payment screen at the till. You can open the order and use the <strong>Payments</strong> tab to see its lines. See <a href="./../selling/pay-and-receipt.html">Pay and receipt</a>.</p><h2 id="terminal-status" tabindex="-1">Terminal status <a class="header-anchor" href="#terminal-status" aria-label="Permalink to &quot;Terminal status&quot;">​</a></h2><p>Payments made through a payment terminal can carry a status. The values are <strong>Pending</strong>, <strong>Authorized</strong>, <strong>Done</strong>, <strong>Reversed</strong> and <strong>Failed</strong>. Switch on the <strong>Terminal Status</strong> column to see it.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Group by <strong>Session</strong> before you close a session. Compare each method total with the counted money.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./orders.html">Orders</a></li><li><a href="./../payments-setup/payment-methods.html">Payment methods</a></li><li><a href="./../sessions/close-session.html">Close a session</a></li></ul>',7))])}const _=o(l,[["render",h]]);export{y as __pageData,_ as default};
